export const useSocket = () => {
  const socket = ref<WebSocket | null>(null);
  const onClose = ref<(() => void | Promise<void>) | null>(null);

  const isReconnecting = ref<boolean>(false);
  const reconnectAttempts = ref<number>(0);
  const reconnectCountdown = ref<number>(0);
  const maxReconnectAttempts = ref<number>(3);
  let reconnectCountdownInterval: NodeJS.Timeout;

  async function connect(url: URL): Promise<void> {
    if (socket.value) return;

    await disconnect();

    return new Promise(async (resolve, reject) => {
      socket.value = new WebSocket(url);

      socket.value.onopen = async () => {
        console.debug('WebSocket connected');
        resolve();
      };

      socket.value.onclose = async () => {
        console.debug('WebSocket closed');
        showToastError('Connection to server lost');
        if (onClose.value) {
          await onClose.value();
        }
        socket.value = null;
        reconnectSocket();
      };

      socket.value.onerror = (error) => {
        console.debug('WebSocket error:', error);
        showToastError(typeof error === 'string' ? `WebSocket error: ${error}` : 'Something went wrong');
        reject(error);
      };
    });
  }

  function reconnectSocket() {
    if (reconnectAttempts.value < maxReconnectAttempts.value) {
      isReconnecting.value = true;
      const delay = 5000; // 5 seconds
      reconnectCountdown.value = delay / 1000;

      clearInterval(reconnectCountdownInterval);
      reconnectCountdownInterval = setInterval(() => {
        if (reconnectCountdown.value > 0) {
          reconnectCountdown.value--;
        } else {
          clearInterval(reconnectCountdownInterval);
        }
      }, 1000);

      setTimeout(() => {
        reconnectAttempts.value++;
        isReconnecting.value = false;
        clearInterval(reconnectCountdownInterval);
      }, delay);
    } else {
      clearInterval(reconnectCountdownInterval);
      showToastError('Max reconnect attempts reached.');
    }
  }

  function send(message: string) {
    if (!socket.value) return;
    socket.value.send(message);
  }

  async function disconnect(): Promise<void> {
    return new Promise((resolve) => {
      if (!socket.value || socket.value.readyState === 3) {
        resolve();
        return;
      }
      socket.value.onclose = () => {
        console.debug('WebSocket disconnected');
        socket.value = null;
        resolve();
      };

      socket.value.close();
    });
  }

  return {
    socket,
    isReconnecting,
    reconnectAttempts,
    maxReconnectAttempts,
    reconnectCountdown,
    connect,
    disconnect,
    send,
    onClose,
  };
};
