import { submitVoiceVerification } from '~/client';
import type { VerificationVoiceSubmitRequest, VerificationVoiceSubmitResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useSubmitVoiceVerification = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: {
      conversationId: string;
      data: VerificationVoiceSubmitRequest;
    }): Promise<VerificationVoiceSubmitResponse> =>
      submitVoiceVerification({
        composable: '$fetch',
        path: { conversation_id: params.conversationId },
        body: ref(params.data),
      }),
    onSuccess: async (_, body) => {
      showToastSuccess(`Signatories created successfully`);
      const queryCache = useQueryCache();
      queryCache.invalidateQueries({ key: ['voice-verification', body.conversationId] });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    submitVoiceVerification: mutateAsync,
    isSubmitVoiceVerificationLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
