export async function waitForValue<T>(refValue: Ref<T>): Promise<void> {
  return new Promise<void>((resolve) => {
    if (refValue.value) {
      resolve();
      return;
    }

    const unwatch = watch(refValue, (newValue) => {
      if (newValue) {
        unwatch();
        resolve();
      }
    });
  });
}
