import { getVoiceVerification } from '~/client';

export const useVerificationVoiceDetails = defineQuery(() => {
  const route = useRoute('verification-voice-id');
  const conversationId = computed(() => route.params.id?.toString() || '');

  const { data, error, isLoading } = useQuery({
    key: () => ['voice-verification', conversationId.value],
    query: () => getVoiceVerification({ composable: '$fetch', path: { conversation_id: conversationId.value } }),
    enabled: () => !!conversationId.value,
  });

  return {
    conversationId,
    voiceVerificationDetails: data,
    error,
    isLoading,
  };
});
