import { createAuthOneTimeToken } from '~/client';
import type {
  VoiceVerificationAudioMessage,
  VoiceVerificationStartMessage,
  VoiceVerificationStopMessage,
  VoiceVerificationCancelMessage,
  VoiceVerificationSignatoryInfos,
} from '~/types/api';
import { useVoiceVerificationStore } from '~/stores/verification/voice';
import { showToastError } from '~/utils/show-toast';
import { useVerificationVoiceDetails } from '~/queries/verification/voice-details';

type VoiceVerificationMessageFromClient =
  | VoiceVerificationStartMessage
  | VoiceVerificationStopMessage
  | VoiceVerificationAudioMessage
  | VoiceVerificationCancelMessage;

export const useVoiceVerification = (voiceVerificationId: string) => {
  const store = useVoiceVerificationStore();
  const { recordState, signatoryInfos, isReadyForSubmission } = storeToRefs(store);
  const { voiceVerificationDetails } = useVerificationVoiceDetails();
  const {
    socket,
    isReconnecting,
    reconnectAttempts,
    maxReconnectAttempts,
    reconnectCountdown,
    connect,
    disconnect,
    send,
    onClose,
  } = useSocket();

  const error = ref<string>();
  const isLoading = ref<boolean>(false);
  const isSocketInitialized = ref<boolean>(false);

  let stream: MediaStream;
  let audioContext: AudioContext | null;
  let audioChunkBuffer: Float32Array[] = []; // Buffer to store recorded audio chunks
  let sendAudioInterval: NodeJS.Timeout | null = null; // Interval for sending recorded audio chunks

  onClose.value = async () => await onResetState();

  watch(reconnectAttempts, async (newVal, oldValue) => {
    if (newVal && newVal !== oldValue) await onStartVerification();
  });

  function handleSocketMessage(event: MessageEvent) {
    const response = JSON.parse(event.data);
    console.debug('Message received:', response);
    const messageType = response.type as VoiceVerificationMessageTypeToClient;
    let message;

    switch (messageType) {
      case 'initialized':
        isSocketInitialized.value = true;
        break;
      case 'signatory_info':
        if (!isSocketInitialized.value) isSocketInitialized.value = true;
        message = response as VoiceVerificationSignatoryInfos;
        store.setSignatoryInfos(message.infos);
        break;
      case 'force_stop':
        stopVerification();
        break;
      case 'ready_for_submission':
        if (!isSocketInitialized.value) isSocketInitialized.value = true;
        store.setReadyForSubmission();
        break;
      case 'error':
        message = response as VoiceVerificationErrorMessage;
        showToastError(message.detail);
        break;
      default:
        console.warn('Unknown message type:', response.type);
    }
  }

  function sendMessage(message: VoiceVerificationMessageFromClient) {
    send(JSON.stringify(message));
  }

  async function onStartVerification() {
    if (isLoading.value) return;

    try {
      isLoading.value = true;
      if (!voiceVerificationDetails.value) {
        error.value = 'Verification details not found.';
        return;
      }

      if (voiceVerificationDetails.value.status === 'new' || voiceVerificationDetails.value.status === 'in_progress') {
        await startVerification(voiceVerificationDetails.value.id);
      } else if (voiceVerificationDetails.value.status == 'ready_for_submit') {
        signatoryInfos.value = (voiceVerificationDetails.value.extracted_signatories?.map((item) => ({
          ...item,
          signed_date: item.signed_date ? item.signed_date : formatDateToFormat(new Date(), 'yyyy-MM-dd'),
        })) || []) as SignatoryInfoResult[];
        isReadyForSubmission.value = true;
      }
    } catch (err: any) {
      if (reconnectAttempts.value >= maxReconnectAttempts.value) navigateTo({ name: 'verification' });
      error.value = err.message ?? 'An error occurred while starting signatory verification.';
    } finally {
      isLoading.value = false;
    }
  }

  async function startVerification(verificationId: string) {
    await onResetState();
    recordState.value = 'starting';
    signatoryInfos.value = [];
    isReadyForSubmission.value = false;

    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const sampleRate = stream.getAudioTracks()[0].getSettings().sampleRate || 48000;
    audioContext = new AudioContext({ sampleRate });

    const audioConfig = createAudioConfig(stream);

    const url = await getWsConnectionURL(verificationId, audioConfig);
    await connect(url);
    if (!socket.value) return;
    socket.value.onmessage = (event: MessageEvent) => handleSocketMessage(event);
    await waitForValue(isSocketInitialized);

    sendMessage({ type: 'start' });
    recordState.value = 'streaming';
    await streamAudio();
  }

  async function getWsConnectionURL(verification_id: string, audio_config: AudioConfig): Promise<URL> {
    const { access_token } = await createAuthOneTimeToken({ composable: '$fetch' });
    const wsUrl = new URL(`${useRuntimeConfig().public.wsBaseURL}/voice_verification/${verification_id}`);

    const params = new URLSearchParams({
      token: access_token,
      sample_rate: audio_config.sample_rate.toString(),
      bits_per_sample: audio_config.bits_per_sample.toString(),
      channels: audio_config.channels.toString(),
      encoding: audio_config.encoding,
    });

    wsUrl.search = params.toString();
    return wsUrl;
  }

  async function streamAudio() {
    if (!audioContext) return;

    await audioContext.audioWorklet.addModule('/audio-processor.js');
    const source = audioContext.createMediaStreamSource(stream);
    const audioProcessorNode = new AudioWorkletNode(audioContext, 'audio-processor');

    audioProcessorNode.port.onmessage = ({ data }) => {
      if (!data || recordState.value !== 'streaming') return;
      audioChunkBuffer.push(new Float32Array(data));

      if (!sendAudioInterval) {
        sendAudioInterval = setInterval(sendBase64EncodedAudio, 250);
      }
    };

    source.connect(audioProcessorNode);
    audioProcessorNode.connect(audioContext.destination);
  }

  function sendBase64EncodedAudio() {
    if (!audioChunkBuffer.length) return;

    const combinedBuffer = audioChunkBuffer.reduce((acc, chunk) => {
      const combined = new Float32Array(acc.length + chunk.length);
      combined.set(acc);
      combined.set(chunk, acc.length);
      return combined;
    }, new Float32Array());
    sendMessage({ type: 'stream_audio', audio_data: arrayBufferToBase64(combinedBuffer.buffer as ArrayBuffer) });
    audioChunkBuffer = [];
  }

  function stopVerification() {
    stopAudioContext();
    stopStream();
  }

  async function cancelVerification() {
    if (recordState.value === 'streaming') {
      stopStream();
    }
    sendMessage({ type: 'cancel' });
    await onResetState();
  }

  function stopAudioContext() {
    audioContext?.close();
    audioContext = null;

    if (sendAudioInterval) {
      clearInterval(sendAudioInterval);
      sendAudioInterval = null;
    }
    audioChunkBuffer = [];
    stopStreamTracks(stream);
  }

  function stopStream() {
    sendMessage({ type: 'stop' });
    recordState.value = 'stopped';
  }

  async function onResetState() {
    await disconnect();
    stopAudioContext();
    store.resetState();
  }

  return {
    error,
    isLoading,
    isReconnecting,
    reconnectAttempts,
    reconnectCountdown,
    onStartVerification,
    cancelVerification,
    stopVerification,
  };
};
