<template>
  <div class="flex flex-col gap-4">
    <AppLoader v-if="isLoading" class="text-center" title="Connecting to the server..." variant="inline" />
    <AppError v-else-if="error" title="Failed to load data" :message="error" />
    <template v-else>
      <AppLoader
        v-if="isReconnecting"
        class="text-center"
        :title="`Attempting to reconnect in ${reconnectCountdown} seconds...`"
        variant="inline"
      />
      <div v-if="recordState === 'streaming'" class="flex flex-col gap-2 items-center px-7">
        <Progress :model-value="100" indicator-class="bg-slate-600" class="bg-accent h-2.5 shim" />
        <p class="text-accent-foreground leading-7">Verification in progress...</p>
      </div>
      <div class="flex flex-col gap-4">
        <Alert v-if="signatoryInfos.length === 0">
          <CircleAlertIcon />
          <AlertTitle>No signatory information recognized yet</AlertTitle>
        </Alert>
        <Card v-for="(signatoryInfo, sIndex) in signatoryInfos" :key="signatoryInfo.id">
          <CardHeader>
            <CardTitle>Signatory Information #{{ sIndex + 1 }}</CardTitle>
          </CardHeader>
          <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-2">
            <VerificationVoiceFormInput
              v-for="(value, key, index) in signatoryInfoLabels"
              :key="index"
              v-model="signatoryInfo[key]"
              :label="signatoryInfoLabels[key]"
              :maska="key === 'zip_code' ? '#####' : undefined"
              :date-picker="key === 'signed_date'"
              :class="{ 'sm:col-span-1': index < 6, 'sm:col-span-2': index >= 6 }"
            />
          </CardContent>
          <CardFooter class="justify-between">
            <Badge
              v-if="signatoryInfo.validation_result"
              class="float-start"
              :variant="signatoryInfo.validation_result === 'valid' ? 'success' : 'destructive'"
              >{{ signatoryInfo.validation_result }}
            </Badge>
            <span v-else />
            <Button variant="outline-destructive" class="float-right" @click="removeSignatory(sIndex)"> Remove</Button>
          </CardFooter>
        </Card>
        <Button
          v-if="isReadyForSubmission"
          :prepend-icon="PlusIcon"
          variant="outline"
          class="mx-auto"
          @click="addNewSignatory"
          >Add New Signatory
        </Button>
      </div>
      <Separator />
      <div class="flex gap-2 flex-wrap">
        <Button variant="outline-destructive" class="h-10 flex-auto min-w-40" @click="onCancelVerification"
          >Cancel
        </Button>
        <Button
          v-if="recordState === 'streaming'"
          class="uppercase h-10 flex-auto"
          variant="destructive"
          :prepend-icon="StopCircleIcon"
          @click="stopVerification"
          >Stop
        </Button>
        <Button
          v-else
          variant="default"
          :disabled="!isSubmitEnabled || !isReadyForSubmission || isSubmitVoiceVerificationLoading"
          :loading="isSubmitVoiceVerificationLoading"
          class="h-10 flex-auto min-w-40"
          @click="submitVerification"
        >
          {{ !isReadyForSubmission && !isReconnecting ? 'Finishing Conversation…' : 'Submit' }}
        </Button>
      </div>
    </template>
  </div>
</template>

<script setup lang="ts">
import { useVoiceVerificationStore } from '~/stores/verification/voice';
import { CircleAlertIcon, PlusIcon, StopCircleIcon } from 'lucide-vue-next';
import SignatoryInfoSchema from '~/constants/validationSchemas/signatoryInfo';
import { useSubmitVoiceVerification } from '~/mutations/verification/voice';
import type { SignatoryVoiceForm } from '~/client';

const props = defineProps({
  conversationId: {
    type: String,
    required: true,
  },
});

const store = useVoiceVerificationStore();
const { recordState, signatoryInfos, isReadyForSubmission } = storeToRefs(store);
const { addNewSignatory, removeSignatory } = store;

const {
  error,
  isLoading,
  isReconnecting,
  reconnectCountdown,
  onStartVerification,
  stopVerification,
  cancelVerification,
} = useVoiceVerification(props.conversationId);

const signatoryInfoLabels: Record<keyof SignatoryVoiceForm, string> = {
  first_name: 'First Name',
  last_name: 'Last Name',
  middle_name: 'Middle Name',
  state: 'State',
  city: 'City',
  county: 'County',
  address_1: 'Address',
  address_2: 'Address (line 2)',
  zip_code: 'ZIP Code',
  signed_date: 'Signed Date',
};

const isSubmitEnabled = computed<boolean>(() => {
  return (
    signatoryInfos.value.every((signatoryInfo) => {
      const parsedResult = SignatoryInfoSchema.safeParse(signatoryInfo);
      return parsedResult.success;
    }) && signatoryInfos.value.length > 0
  );
});

async function onCancelVerification() {
  await cancelVerification();
  await navigateTo({ name: 'verification-signatory' });
}

const { submitVoiceVerification, isSubmitVoiceVerificationLoading } = useSubmitVoiceVerification();

async function submitVerification() {
  try {
    const filteredInfo = signatoryInfos.value.map((item) => {
      const { id, other_data, validation_result, signed_date, ...rest } = item;
      const parcedRest = SignatoryInfoSchema.safeParse(rest);
      if (!parcedRest.success) {
        throw new Error('Validation failed for signatory information');
      }
      const { first_name, last_name, address_1 } = parcedRest.data;
      return {
        ...rest,
        first_name,
        last_name,
        address_1,
        signed_date: signed_date ? signed_date : formatDateToFormat(new Date(), 'yyyy-MM-dd'),
      };
    });
    await submitVoiceVerification({ conversationId: props.conversationId, data: { signatories: filteredInfo } });
    recordState.value = 'submitted';
  } catch (error) {
    console.error('Validation error:', error);
    showToastError('Please ensure all signatory information is valid.');
    return;
  }
}

onMounted(async () => {
  await onStartVerification();
});

onBeforeRouteLeave(async () => {
  await cancelVerification();
  store.resetState();
});
</script>

<style scoped lang="scss"></style>
